(* [comment removed for export] *)
Section LE64F.
  Variables (ra sp gp tp t0 t1 t2 a0 a2 a3 a4 a5 a6 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : fmem) (S : Z) (bs : list Z) (POST : machine_state -> Prop).
  Hypothesis SRC : bytes_at psegs m S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.

  Notation ST pc x8 x9 x11 x17 x18 x30 x31 :=
    (MS (mkR ra sp gp tp t0 t1 t2 x8 x9 a0 x11 a2 a3 a4 a5 a6 x17 x18 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 x30 x31)
        F (Z_to_bv 64 pc) fc None m (seg_rom psegs)).

  Ltac ldb0 p k :=
    let RX := fresh "RX" in
    pose proof (src_rd psegs m S bs (p + k) SRC ltac:(lia)) as RX;
    rewrite ?Z.add_assoc, ?Z.add_0_r in RX;
    zstep; cbv beta; clear RX.

  Lemma fm_ld : forall (p : Z) (x8 x9 x17 x18 x30 x31 : word),
    0 <= p -> p + 8 <= zlen bs ->
    (forall (y8 y9 y18 y30 y31 : word),
       evt psegs POST (ST 0x1c7a0 y8 y9 (Z_to_bv 64 (S + p)) (Z_to_bv 64 (le64v bs p)) y18 y30 y31)) ->
    evt psegs POST (ST 0x1c748 x8 x9 (Z_to_bv 64 (S + p)) x17 x18 x30 x31).
Proof.
