  Notation ST pc mm x5 x6 x7 x8 x9 x11 x13 x17 x18 x29 x30 x31 :=
    (MS (mkR ra sp gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 (S + 8)) x11 (Z_to_bv 64 S) x13
             (Z_to_bv 64 ZEROFILLED_F) (Z_to_bv 64 TB) (Z_to_bv 64 TB) x17 x18 x19 x20 (Z_to_bv 64 (DST + dcap - 3)) x22
             x23 x24 x25 x26 x27 (Z_to_bv 64 64) x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  (* [comment removed for export] *)
  Ltac osb OUTA LJ :=
    let SOK := fresh "SOK" in
    lazymatch type of OUTA with u8arr _ ?mm ?D (map (Z_to_bv 8) ?o ++ ?j) =>
    pose proof (u8arr_store_ok psegs mm D _ (zlen o) (wa (D + zlen o)) OUTA
                  ltac:(repeat (rewrite length_app || rewrite length_map); cbn [length]; lia) eq_refl) as SOK;
    zstep;
    lazymatch goal with
    | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (wa ?E) _) _) =>
        replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (Z_to_bv 64 ?E) _) _) =>
        replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    end;
    rewrite le1_lit;
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ [Z_to_bv 8 ?v]) _) =>
      let OUT2 := fresh "OUTA" in
      let LJ2 := fresh "LJ" in
      pose proof (out_sb psegs mm D o j v OUTA ltac:(lia)) as OUT2;
      let LO2 := fresh "LO" in
      assert (LO2 : zlen (o ++ [v]) = zlen o + 1) by (rewrite length_app; cbn [length]; lia);
      assert (LJ2 : zlen (List.tl j) = dcap - zlen (o ++ [v])) by (rewrite zlen_tl by lia; lia);
      clear OUTA LJ; store_done; rename OUT2 into OUTA; rename LJ2 into LJ
    end end.

  (* [comment removed for export] *)
  Lemma fm_dec4 : forall d0 s1 s2 out o0 s1a d1 o1 s2a d2 o2 s1b d3 o3 s2b d4 m1 (x8 x9 x18 x29 x30 x31 : word),
    decode_sym dt true s1 d0 = Ok (o0, s1a, d1) -> decode_sym dt true s2 d1 = Ok (o1, s2a, d2) ->
    decode_sym dt true s1a d2 = Ok (o2, s1b, d3) -> decode_sym dt true s2a d3 = Ok (o3, s2b, d4) ->
    0 <= bd_bits d0 <= 64 -> 0 <= bd_cont d0 < 2^64 -> zlen out + 4 <= dcap ->
    sm_inv m0 DST dcap m1 out ->
    (forall m2 (y8 y9 y18 y29 y30 y31 : word), sm_inv m0 DST dcap m2 (out ++ [o0; o1; o2; o3]) ->
       evt psegs POST (ST 0x1c864 m2 (Z_to_bv 64 s1b) (Z_to_bv 64 s2b) (Z_to_bv 64 (DST + zlen out + 4)) y8 y9
                          (Z_to_bv 64 (S + bd_ptr d0)) (Z_to_bv 64 (bd_bits d4)) (Z_to_bv 64 (bd_cont d0)) y18 y29 y30 y31)) ->
    evt psegs POST (ST 0x1c7a8 m1 (Z_to_bv 64 s1) (Z_to_bv 64 s2) (Z_to_bv 64 (DST + zlen out)) x8 x9
