  (* [comment removed for export] *)
  Definition fml_body (f : nat) (x : dec) (st : dstatus) (d0 : bitD) : res dec :=
    if dstatus_eqb st Unfinished && (FseNCount.Zlength (de_out x) <? dcap - 3) then
      let! q1 := decode_sym dt true (de_s1 x) d0 in let '(o0, s1a, d1) := q1 in
      let! q2 := decode_sym dt true (de_s2 x) d1 in let '(o1, s2a, d2) := q2 in
      let! q3 := decode_sym dt true s1a d2 in let '(o2, s1b, d3) := q3 in
      let! q4 := decode_sym dt true s2a d3 in let '(o3, s2b, d4) := q4 in
      main_loop bs dt dcap true f (mkDec (de_out x ++ [o0; o1; o2; o3]) s1b s2b d4)
    else Ok (mkDec (de_out x) (de_s1 x) (de_s2 x) d0).

  Lemma fmain_loop_S : forall f x, main_loop bs dt dcap true (Datatypes.S f) x =
    let! r := reload_dstream bs (de_bd x) in let '(st, d0) := r in fml_body f x st d0.
Proof.
