  Notation HEADF x mm x8 x9 x18 x29 x30 x31 :=
    (ST 0x1c704 mm (Z_to_bv 64 (de_s1 x)) (Z_to_bv 64 (de_s2 x)) (Z_to_bv 64 (DST + zlen (de_out x))) x8 x9
        (Z_to_bv 64 (S + bd_ptr (de_bd x))) (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (bd_cont (de_bd x))) x18 x29 x30 x31).
  Notation EXITF r mm y8 y9 y18 y29 y30 y31 :=
    (ST 0x1c86c mm (Z_to_bv 64 (de_s1 r)) (Z_to_bv 64 (de_s2 r)) (Z_to_bv 64 (DST + zlen (de_out r))) y8 y9
        (Z_to_bv 64 (bd_reg S (de_bd r))) (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (bd_cont (de_bd r))) y18 y29 y30 y31).

  Definition fm_K (r : dec) : Prop :=
    forall m2 (y8 y9 y18 y29 y30 y31 : word), sm_okr dcap bs r -> sm_inv m0 DST dcap m2 (de_out r) ->
      evt psegs POST (EXITF r m2 y8 y9 y18 y29 y30 y31).

  Lemma fm_after : forall f out s1 s2 d st c b p r m1 (x8 x9 x18 x29 x30 x31 : word),
    (forall x' r' m1' (x8' x9' x18' x29' x30' x31' : word),
       main_loop bs dt dcap true f x' = Ok r' -> sm_ok dcap bs x' -> sm_inv m0 DST dcap m1' (de_out x') -> fm_K r' ->
       evt psegs POST (HEADF x' m1' x8' x9' x18' x29' x30' x31')) ->
    fml_body f (mkDec out s1 s2 d) st (mkBD c b p false) = Ok r ->
    bitd_ok bs (mkBD c b p false) -> b <= 64 -> zlen out <= dcap -> Forall (fun c => 0 <= c < 256) out ->
    dstatus_eqb st Unfinished = negb (bv_unsigned x29 =? 0) ->
    sm_inv m0 DST dcap m1 out -> fm_K r ->
    evt psegs POST (ST 0x1c7a0 m1 (Z_to_bv 64 s1) (Z_to_bv 64 s2) (Z_to_bv 64 (DST + zlen out)) x8 x9 (Z_to_bv 64 (S + p))
                       (Z_to_bv 64 b) (Z_to_bv 64 c) x18 x29 x30 x31).
Proof.
